//! 🔁️ Closed snapshot refusal transport preserves all independent original causes.
use super::{NativeSnapshotCause,NativeSnapshotFailure,NativeSnapshotAllocationFailure};
use semio_framework_value::{DslValue,NativeEncodeControl,ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,RetainedWorkOutcome,ToValue,FromValue};
use semio_framework_value_native_owned::{OriginalReceivingPrimary,native_decoding::NativeDecodeControl};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"native snapshot failure differs from its closed transport schema")}
fn fields<'a,const N:usize>(value:&'a DslValue,names:[&str;N])->Result<[&'a DslValue;N],ValueError>{
 let DslValue::Object(entries)=value else{return Err(invalid())};if entries.len()!=N{return Err(invalid())}
 let mut result=[None;N];for(key,value)in entries{let Some(index)=names.iter().position(|name|*name==key)else{return Err(invalid())};if result[index].replace(value).is_some(){return Err(invalid())}}
 Ok(result.map(|value|value.expect("closed transport has every declared field")))
}
fn optional_error(value:Option<&ValueError>,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{match value{Some(value)=>value.to_value_controlled(control),None=>Ok(DslValue::Null)}}
pub fn optional_refusal(value:Option<&semio_framework_value_control_contract::NativeAllocationRefusal>,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{match value{None=>Ok(DslValue::Null),Some(semio_framework_value_control_contract::NativeAllocationRefusal::Owned(error))=>error.to_value_controlled(control),Some(semio_framework_value_control_contract::NativeAllocationRefusal::Retained(_))=>Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original allocation refusal must be resolved by its owner before encoding"))}}
fn object(control:&mut NativeEncodeControl<'_>,count:usize,produce:impl FnOnce(&mut Vec<(String,DslValue)>,&mut NativeEncodeControl<'_>)->Result<(),ValueError>)->Result<DslValue,ValueError>{
 control.scoped_stage(|control|{control.begin_stage(count)?;let mut fields=DslValue::object_encoding_controlled(count,control)?;produce(fields.get_mut(),control)?;Ok(DslValue::Object(fields.take()))})
}
fn field(entries:&mut Vec<(String,DslValue)>,name:&str,value:DslValue,control:&mut NativeEncodeControl<'_>)->Result<(),ValueError>{DslValue::push_encoding_controlled(entries,name,value,control)?;control.step()}
pub fn retirement_value(value:&semio_framework_value::OriginalRetirementFailure,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{
 let mut depth=0usize;let mut probe=Some(value);while let Some(node)=probe{control.checkpoint()?;depth=depth.checked_add(1).ok_or_else(invalid)?;control.check_additional_depth(depth)?;probe=node.child();}
 let mut root=DslValue::Null.guard_decoded();let mut slot=root.get_mut();let mut original=Some(value);let mut node_depth=0usize;
 while let Some(node)=original{node_depth=node_depth.checked_add(1).ok_or_else(invalid)?;let shell=control.scoped_additional_depth(node_depth,|control|object(control,6,|entries,control|{let value=optional_error(node.primary(),control)?;field(entries,"primary",value,control)?;let value=optional_error(node.work_refusal(),control)?;field(entries,"workRefusal",value,control)?;let value=optional_error(node.receipt_refusal(),control)?;field(entries,"receiptRefusal",value,control)?;let value=optional_refusal(node.allocation_refusal(),control)?;field(entries,"allocationRefusal",value,control)?;let value=match node.progress_override(){Some(progress)=>progress.to_value_controlled(control)?,None=>DslValue::Null};field(entries,"progressOverride",value,control)?;field(entries,"child",DslValue::Null,control)}))?;*slot=shell;let DslValue::Object(entries)=slot else{return Err(invalid())};slot=&mut entries.iter_mut().find(|(key,_)|key=="child").ok_or_else(invalid)?.1;original=node.child();}
 Ok(root.take())
}

fn allocation_request_value(request:Option<(usize,usize,usize,usize)>,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{match request{None=>Ok(DslValue::Null),Some((bytes,owned,next,maximum))=>object(control,4,|entries,control|{let value=bytes.to_value_controlled(control)?;field(entries,"bytes",value,control)?;let value=owned.to_value_controlled(control)?;field(entries,"ownedBytes",value,control)?;let value=next.to_value_controlled(control)?;field(entries,"nextOwnedBytes",value,control)?;let value=maximum.to_value_controlled(control)?;field(entries,"maximumBytes",value,control)})}}
fn decode_allocation_value(value:&semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{object(control,8,|entries,control|{let kind=DslValue::String(control.copy_text("decode")?);field(entries,"type",kind,control)?;let v=allocation_request_value(value.request.map(|r|(r.bytes,r.owned_bytes,r.next_owned_bytes,r.maximum_bytes)),control)?;field(entries,"request",v,control)?;let v=value.admitted.to_value_controlled(control)?;field(entries,"admitted",v,control)?;let v=optional_error(value.primary.as_ref(),control)?;field(entries,"primary",v,control)?;let v=optional_refusal(value.quote_refusal.as_ref(),control)?;field(entries,"quoteRefusal",v,control)?;let v=optional_error(value.extent_refusal.as_ref(),control)?;field(entries,"extentRefusal",v,control)?;let v=optional_refusal(value.settlement_refusal.as_ref(),control)?;field(entries,"settlementRefusal",v,control)?;let v=value.actual.to_value_controlled(control)?;field(entries,"actual",v,control)})}
fn encode_allocation_value(value:&semio_framework_value::native_encoding::NativeEncodeAllocationOutcome,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{object(control,10,|entries,control|{let kind=DslValue::String(control.copy_text("encode")?);field(entries,"type",kind,control)?;let v=allocation_request_value(value.request.map(|r|(r.bytes,r.owned_bytes,r.next_owned_bytes,r.maximum_bytes)),control)?;field(entries,"request",v,control)?;let v=value.admitted.to_value_controlled(control)?;field(entries,"admitted",v,control)?;let v=optional_error(value.primary.as_ref(),control)?;field(entries,"primary",v,control)?;let v=optional_refusal(value.forwarded_quote.as_ref(),control)?;field(entries,"forwardedQuote",v,control)?;let v=optional_refusal(value.scoped_quote.as_ref(),control)?;field(entries,"scopedQuote",v,control)?;let v=optional_error(value.extent_refusal.as_ref(),control)?;field(entries,"extentRefusal",v,control)?;let v=optional_refusal(value.forwarded_refusal.as_ref(),control)?;field(entries,"forwardedRefusal",v,control)?;let v=optional_refusal(value.scoped_refusal.as_ref(),control)?;field(entries,"scopedRefusal",v,control)?;let v=value.actual.to_value_controlled(control)?;field(entries,"actual",v,control)})}
fn allocation_value(value:&NativeSnapshotAllocationFailure,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{
 match value{
  NativeSnapshotAllocationFailure::Encode(value)=>encode_allocation_value(value,control),
  NativeSnapshotAllocationFailure::Decode(value)=>decode_allocation_value(value,control)
 }
}
fn receiving_primary_value(value:&OriginalReceivingPrimary,tagged:bool,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{object(control,if tagged{12}else{11},|entries,control|{if value.receipt_completion_pending(){return Err(invalid())}if tagged{let kind=DslValue::String(control.copy_text("receiving")?);field(entries,"type",kind,control)?;}let field_value=optional_error(value.primary.as_ref(),control)?;field(entries,"primary",field_value,control)?;let field_value=optional_error(value.quote_refusal.as_ref(),control)?;field(entries,"quoteRefusal",field_value,control)?;let field_value=optional_error(value.allocation_refusal.as_ref(),control)?;field(entries,"allocationRefusal",field_value,control)?;let field_value=optional_error(value.work_refusal.as_ref(),control)?;field(entries,"workRefusal",field_value,control)?;let field_value=optional_error(value.work_overrun.as_ref(),control)?;field(entries,"workOverrun",field_value,control)?;let field_value=match &value.allocation_failure{Some(allocation)=>{if !allocation.progress.request_is_complete(){return Err(invalid())}object(control,13,|entries,control|{let v=optional_error(allocation.primary.as_ref(),control)?;field(entries,"primary",v,control)?;let v=optional_error(allocation.admission.as_ref(),control)?;field(entries,"admission",v,control)?;let v=optional_refusal(allocation.forwarded_admission.as_ref(),control)?;field(entries,"forwardedAdmission",v,control)?;let v=optional_refusal(allocation.scoped_admission.as_ref(),control)?;field(entries,"scopedAdmission",v,control)?;let v=optional_refusal(allocation.forwarded_quote.as_ref(),control)?;field(entries,"forwardedQuote",v,control)?;let v=optional_refusal(allocation.scoped_quote.as_ref(),control)?;field(entries,"scopedQuote",v,control)?;let v=optional_refusal(allocation.forwarded_post.as_ref(),control)?;field(entries,"forwardedPost",v,control)?;let v=optional_refusal(allocation.scoped_post.as_ref(),control)?;field(entries,"scopedPost",v,control)?;let v=optional_refusal(allocation.forwarded_cancel.as_ref(),control)?;field(entries,"forwardedCancel",v,control)?;let v=optional_refusal(allocation.scoped_cancel.as_ref(),control)?;field(entries,"scopedCancel",v,control)?;let v=optional_error(allocation.receipt.as_ref(),control)?;field(entries,"receipt",v,control)?;let v=optional_error(allocation.extent.as_ref(),control)?;field(entries,"extent",v,control)?;let v=object(control,5,|entries,control|{let v=allocation.progress.prior_admitted_bytes.to_value_controlled(control)?;field(entries,"priorAdmittedBytes",v,control)?;let v=allocation.progress.requested_bytes.to_value_controlled(control)?;field(entries,"requestedBytes",v,control)?;let v=allocation.progress.maximum_bytes.to_value_controlled(control)?;field(entries,"maximumBytes",v,control)?;let v=allocation.progress.admitted_bytes.to_value_controlled(control)?;field(entries,"admittedBytes",v,control)?;let v=allocation.progress.actual_capacity_bytes.to_value_controlled(control)?;field(entries,"actualCapacityBytes",v,control)})?;field(entries,"progress",v,control)})?},None=>DslValue::Null};field(entries,"allocationFailure",field_value,control)?;let field_value=optional_error(value.receipt_refusal.as_ref(),control)?;field(entries,"receiptRefusal",field_value,control)?;let field_value=optional_error(value.receipt_completion(),control)?;field(entries,"receiptCompletion",field_value,control)?;let field_value=match &value.native_allocation{Some(outcome)=>decode_allocation_value(outcome,control)?,None=>DslValue::Null};field(entries,"nativeAllocation",field_value,control)?;let field_value=match &value.retirement_failure{Some(retirement)=>retirement_value(retirement,control)?,None=>DslValue::Null};field(entries,"retirementFailure",field_value,control)?;let field_value=value.progress.to_value_controlled(control)?;field(entries,"progress",field_value,control)})}
fn encode_effect_value(value:&semio_framework_value::native_encoding::NativeEncodeEffectFailure,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{object(control,12,|entries,control|{for(name,error)in [("primary",value.primary.as_ref()),("context",value.context.as_ref()),("invariant",value.invariant.as_ref()),("physicalInvariant",value.physical_invariant.as_ref()),("capacityInvariant",value.capacity_invariant.as_ref()),("markerFailure",value.marker_failure.as_ref()),("work",value.work.as_ref()),("workOverrun",value.work_overrun.as_ref()),("local",value.local.as_ref()),("physical",value.physical.as_ref())]{let value=optional_error(error,control)?;field(entries,name,value,control)?}let receipt=match &value.physical_receipt{Some(value)=>receiving_primary_value(value,false,control)?,None=>DslValue::Null};field(entries,"physicalReceipt",receipt,control)?;let allocation=match &value.allocation{Some(value)=>encode_allocation_value(value,control)?,None=>DslValue::Null};field(entries,"allocation",allocation,control)})}
impl NativeSnapshotFailure{
 /// 🛫️ Projects all causes through the supplied original encode control.
 pub fn to_value_controlled(&self,control:&mut NativeEncodeControl<'_>)->Result<DslValue,ValueError>{
  object(control,8,|entries,control|{
   let cause=match &self.cause{
    None=>DslValue::Null,
    Some(NativeSnapshotCause::Value(value))=>object(control,2,|entries,control|{let kind=DslValue::String(control.copy_text("value")?);field(entries,"type",kind,control)?;let value=value.to_value_controlled(control)?;field(entries,"value",value,control)})?,
    Some(NativeSnapshotCause::Receiving(value))=>receiving_primary_value(value,true,control)?,
    Some(NativeSnapshotCause::Retirement(value))=>object(control,2,|entries,control|{let kind=DslValue::String(control.copy_text("retirement")?);field(entries,"type",kind,control)?;let field_value=retirement_value(value,control)?;field(entries,"value",field_value,control)})?
   };field(entries,"cause",cause,control)?;let value=match &self.allocation{Some(value)=>allocation_value(value,control)?,None=>DslValue::Null};field(entries,"allocation",value,control)?;let value=match &self.encode_effect{Some(value)=>encode_effect_value(value,control)?,None=>DslValue::Null};field(entries,"encodeEffect",value,control)?;
   let value=optional_error(self.receipt_refusal.as_ref(),control)?;field(entries,"receiptRefusal",value,control)?;let value=optional_error(self.context_refusal.as_ref(),control)?;field(entries,"contextRefusal",value,control)?;let value=optional_error(self.work_refusal.as_ref(),control)?;field(entries,"workRefusal",value,control)?;let value=optional_error(self.settlement_refusal.as_ref(),control)?;field(entries,"settlementRefusal",value,control)?;let value=self.progress.to_value_controlled(control)?;field(entries,"progress",value,control)
  })
 }
}
